with recursive t(id,anc) as (select institution_id,institution_id from institutions union all select t.id, i.parent_id from t join institutions i on i.institution_id=t.anc where i.parent_id is not null), kw as (select distinct w.work_id from authorships s join t on t.id=s.institution_id and t.anc='I07' join works w using(work_id) where w.type in ('ART','REV')) select kw.work_id, (select count(*) from citations where cited_work_id=kw.work_id) + (select count(*) from citations c join works v on v.work_id=c.cited_work_id where v.version_of=kw.work_id) n from kw order by n desc, 1 limit 4;
